// Smooth SVG paths keep the charts crisp at any responsive width.
export function sparkPath(
  values: number[],
  width = 100,
  height = 40,
  padding = 3,
) {
  const max = Math.max(...values, 1);
  const min = Math.min(...values, 0);
  const points = values.map((v, i) => [
    padding + (i * (width - 2 * padding)) / (values.length - 1),
    height - padding - ((v - min) / (max - min || 1)) * (height - 2 * padding),
  ]);
  return points.reduce((path, [x, y], i) => {
    if (!i) return `M${x},${y}`;
    const [px, py] = points[i - 1];
    const mid = (px + x) / 2;
    return `${path} C${mid},${py} ${mid},${y} ${x},${y}`;
  }, "");
}

