export function TrendChart({ period = "24小时" }: { period?: string }) {
  const [hover, setHover] = useState<number | null>(null);
  const uid = useId().replace(/:/g, "");
  const data =
    period === "7天"
      ? [290, 340, 270, 380, 420, 360, 460, 400, 530, 610, 550, 720]
      : period === "30天"
        ? [220, 310, 280, 440, 360, 510, 430, 630, 570, 680, 610, 780]
        : [
            180, 160, 110, 135, 260, 340, 285, 440, 360, 530, 655, 580, 470,
            620, 540, 700, 610, 770, 640, 735, 590, 630, 520, 580,
          ];
  const negative = data.map((x, i) => x * (0.19 + (i % 4) * 0.025));
  const width = 720;
  const height = 210;
  const path = (values: number[]) => {
    const pts = values.map((v, i) => [
      (i * width) / (values.length - 1),
      height - (v / 1000) * height,
    ]);
    return pts.reduce((p, [x, y], i) => {
      if (!i) return `M${x},${y}`;
      const [px, py] = pts[i - 1];
      const mid = (x + px) / 2;
      return `${p} C${mid},${py} ${mid},${y} ${x},${y}`;
    }, "");
  };
  const labels =
    period === "24小时"
      ? ["昨14:30", "18:30", "22:30", "02:30", "06:30", "10:30", "今14:30"]
      : period === "7天"
        ? ["10/28", "10/29", "10/30", "10/31", "11/01", "11/02", "11/03"]
        : ["10/05", "10/10", "10/15", "10/20", "10/25", "10/30", "11/03"];
  return (
    <div className="trend-chart">
      <div className="chart-unit">单位：条</div>
      <div className="chart-plot">
        <div className="y-labels">
          {["1,000", "750", "500", "250", "0"].map((s) => (
            <span key={s}>{s}</span>
          ))}
        </div>
        <svg
          viewBox={`-2 -3 ${width + 4} ${height + 6}`}
          preserveAspectRatio="none"
          role="img"
          aria-label={`${period}舆情声量与负面舆情趋势`}
          onMouseLeave={() => setHover(null)}
          onMouseMove={(e) => {
            const r = e.currentTarget.getBoundingClientRect();
            setHover(
              Math.max(
                0,
                Math.min(
                  data.length - 1,
                  Math.round(
                    ((e.clientX - r.left) / r.width) * (data.length - 1),
                  ),
                ),
              ),
            );
          }}
        >
          <defs>
            <linearGradient id={`fill-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#527cf1" stopOpacity=".18" />
              <stop offset="100%" stopColor="#527cf1" stopOpacity=".01" />
            </linearGradient>
          </defs>
          {[0, 1, 2, 3, 4].map((i) => (
            <line
              key={i}
              x1="0"
              x2={width}
              y1={(i * height) / 4}
              y2={(i * height) / 4}
              stroke="#edf0f5"
              strokeDasharray="4 4"
            />
          ))}
          <path
            d={`${path(data)} L${width},${height} L0,${height} Z`}
            fill={`url(#fill-${uid})`}
          />
          <path d={path(data)} stroke="#4c77ed" strokeWidth="2.5" fill="none" />
          <path
            d={path(negative)}
            stroke="#ecad73"
            strokeWidth="2"
            fill="none"
          />
          {hover !== null && (
            <g>
              <line
                x1={(hover * width) / (data.length - 1)}
                x2={(hover * width) / (data.length - 1)}
                y1={0}
                y2={height}
                stroke="#a5b6e7"
                strokeDasharray="4 4"
              />
              <circle
                cx={(hover * width) / (data.length - 1)}
                cy={height - (data[hover] / 1000) * height}
                r="4"
                fill="#4c77ed"
                stroke="white"
                strokeWidth="2"
              />
            </g>
          )}
        </svg>
        {hover !== null && (
          <div
            className="chart-tooltip"
            style={{
              left: `${Math.min(75, Math.max(9, (hover / (data.length - 1)) * 88))}%`,
            }}
          >
            观察点 {hover + 1}
            <b>舆情声量 {data[hover]} 条</b>
            <span>负面舆情 {Math.round(negative[hover])} 条</span>
          </div>
        )}
      </div>
      <div className="x-labels">
        {labels.map((s) => (
          <span key={s}>{s}</span>
        ))}
      </div>
    </div>
  );
}

