export function toneFor(value: string) {
  return value === "高风险" || value === "负面"
    ? "red"
    : value === "中风险" || value === "待确认" || value === "待审核"
      ? "orange"
      : value === "正面" ||
          value === "已发布" ||
          value === "已确认" ||
          value === "有效"
        ? "green"
        : value === "复核中"
          ? "blue"
          : "neutral";
}
